def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)

    # Find contiguous non-background runs on each outer edge.
    def runs(line):
        result = []
        i = 0
        while i < len(line):
            if line[i] == bg:
                i += 1
                continue
            color, start = line[i], i
            while i < len(line) and line[i] == color:
                i += 1
            if i - start >= 2:
                result.append((color, start, i - 1))
        return result

    candidates = []
    for side, line in (
        ("top", grid[0]),
        ("bottom", grid[-1]),
        ("left", [grid[r][0] for r in range(h)]),
        ("right", [grid[r][-1] for r in range(h)]),
    ):
        for color, start, end in runs(line):
            candidates.append((side, color, start, end))

    pairs = []
    for a in candidates:
        for b in candidates:
            if a[0] == "top" and b[0] == "bottom":
                orient = "horizontal"
            elif a[0] == "left" and b[0] == "right":
                orient = "vertical"
            else:
                continue
            if a[1] == b[1] and a[3] - a[2] == b[3] - b[2]:
                pairs.append((orient, a, b))

    if not pairs:
        return out

    # The scattered color is the non-background, non-bar color.
    bar_color = pairs[0][1][1]
    marker_colors = [c for c in counts if c not in (bg, bar_color)]
    if not marker_colors:
        return out
    marker_color = max(marker_colors, key=lambda c: counts[c])
    markers = [(r, c) for r in range(h) for c in range(w)
               if grid[r][c] == marker_color]

    def alignment_score(pair, source):
        orient, a, b = pair
        run = a if source == a[0] else b
        lo, hi = run[2], run[3]
        if orient == "horizontal":
            return sum(lo <= c <= hi for r, c in markers)
        return sum(lo <= r <= hi for r, c in markers)

    # Choose the edge bar whose span contains the marker pattern.
    best = None
    for pair in pairs:
        orient, a, b = pair
        for source in (a[0], b[0]):
            score = alignment_score(pair, source)
            if best is None or score > best[0]:
                best = (score, pair, source)

    _, (orient, a, b), source = best
    src = a if a[0] == source else b
    dst = b if src is a else a
    src_lo, src_hi = src[2], src[3]
    dst_lo = dst[2]
    offsets = set()

    if orient == "horizontal":
        for r, c in markers:
            if src_lo <= c <= src_hi:
                offsets.add(c - src_lo)
                if source == "top":
                    for rr in range(1, r):
                        if out[rr][c] != bar_color:
                            out[rr][c] = marker_color
                else:  # bottom
                    for rr in range(r + 1, h - 1):
                        if out[rr][c] != bar_color:
                            out[rr][c] = marker_color

        # Copy the marker pattern to the opposite edge and extend it across.
        for off in offsets:
            cc = dst_lo + off
            for rr in range(h):
                if out[rr][cc] != bar_color:
                    out[rr][cc] = marker_color

    else:  # vertical bars on left and right
        for r, c in markers:
            if src_lo <= r <= src_hi:
                offsets.add(r - src_lo)
                if source == "left":
                    for cc in range(1, c):
                        if out[r][cc] != bar_color:
                            out[r][cc] = marker_color
                else:  # right
                    for cc in range(c + 1, w - 1):
                        if out[r][cc] != bar_color:
                            out[r][cc] = marker_color

        for off in offsets:
            rr = dst_lo + off
            for cc in range(w):
                if out[rr][cc] != bar_color:
                    out[rr][cc] = marker_color

    # Mark the original scattered cells.
    for r, c in markers:
        out[r][c] = 4
    return out
